<?php
namespace App\Modules\CostAccounting\Domain\Models;
use App\Models\User; use App\Modules\CostAccounting\Domain\Enums\CostPeriodStatus; use Illuminate\Database\Eloquent\Attributes\Fillable; use Illuminate\Database\Eloquent\Concerns\HasUlids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
#[Fillable(['year','month','status','processed_flour_quantity','standard_labor_rate_per_kg','labor_rate_reason','opened_at','opened_by','closed_at','closed_by','reopened_at','reopened_by'])]
class CostPeriod extends Model { use HasUlids; public function utilities():HasMany{return $this->hasMany(UtilityCostRecord::class);} public function rates():HasMany{return $this->hasMany(OverheadRate::class);} public function poolEntries():HasMany{return $this->hasMany(CostPoolEntry::class);} public function opener():BelongsTo{return $this->belongsTo(User::class,'opened_by');} public function label():string{return sprintf('%04d-%02d',$this->year,$this->month);} protected function casts():array{return ['year'=>'integer','month'=>'integer','status'=>CostPeriodStatus::class,'processed_flour_quantity'=>'decimal:6','standard_labor_rate_per_kg'=>'integer','opened_at'=>'datetime','closed_at'=>'datetime','reopened_at'=>'datetime'];} }
